head.script:
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name ins_search
 * @description 발행기관 신규/변경 접수 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.ins_search = function() {
    if ($c.stf.compareFromToDate2(edt_pISUR_APPL_SDD, edt_pISUR_APPL_EDD) === false) {
        return false;
    }
    const url = "/listingCommon.do?SCREN_ID=" + "ULDINS05700.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS05700_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.corpinfo.select.readCorpIssInstPrcListView" + "&{P}ISUR_APPL_SDD=" + edt_pISUR_APPL_SDD.getValue() + "&{P}ISUR_APPL_EDD=" + edt_pISUR_APPL_EDD.getValue() + "&{P}ISUR_APPL_TP_CD=" + cmb_pISUR_APPL_TP_CD.getValue() + "&{P}ISUR_CD=" + txb_pISUR_CD.getValue() +
        // "&{P}ISUR_NM=" +  txb_pISUR_NM.value +
        "&{P}PROC=" + cmb_pPROC.getValue();
    // alert(getObjectValue(cmb_pISUR_APPL_TP_CD));
    // alert(getObjectValue(cmb_pPROC));

    dts_List.DataID = encodeURI(url);
    dts_List.reset();

};
scwin.arrPar = new Array();

/**
 * @method
 * @name getParam
 * @description 전달 값을 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue(); // ISUR_APPL_ID
    //    arrPar[1] = txb_param2.value; // 발행기관코드명

    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    scwin.arrPar, length;
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    ins_combo_set(dts_ISUR_APPL_TP_CD, "ULDINS05700.xml", SCREN_PROCS_TP_CD_01, "03433", "ALL"); // 03433 - 신청구분
    $c.cm.PanelToGroupBox(panel_1);
    txb_param1.hide();
    txb_param2.hide();
    $c.stf.setFromToDate(1, edt_pISUR_APPL_SDD, edt_pISUR_APPL_EDD);
    edt_pISUR_APPL_SDD.focus();
};

/**
 * @method
 * @name btn_search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_search_onclick = function() {
    scwin.ins_search();
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    await $c.win.alert(dts_List);

};

/**
 * @method
 * @name img_ISUR_APPL_SDD_onclick
 * @description img_ISUR_APPL_SDD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ISUR_APPL_SDD_onclick = function() {
    popUpCalendar2(edt_pISUR_APPL_SDD);
};

/**
 * @method
 * @name img_ISUR_APPL_EDD_onclick
 * @description img_ISUR_APPL_EDD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ISUR_APPL_EDD_onclick = function() {
    popUpCalendar2(edt_pISUR_APPL_EDD);
};

/**
 * @method
 * @name dts_ISUR_APPL_TP_CD_OnLoadCompleted
 * @description dts_ISUR_APPL_TP_CD 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ISUR_APPL_TP_CD_OnLoadCompleted = function(rowcount) {
    cmb_pISUR_APPL_TP_CD.setSelectedIndex(0);
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    // alert('dts_List.OnLoadCompleted('+rowcount+')');
    if (dts_List.errorMsg) {
        await $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    txb_param1.setValue("");

};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = function(row, colid) {
    if (row === 0) return;
    txb_param1.setValue(dts_List.getCellData(row, "ISUR_APPL_ID"));
    // txb_param2.value = dts_List.NameValue(row,"ISUR_NM");
    fn_GetPar = scwin.getParam;
    ins_popupOpen("", "", "ULDINS91700", "발행기관 신청 상세정보", "1240", "530");
};

/**
 * @method
 * @name txb_pISUR_CD_onkeyup
 * @description txb_pISUR_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_pISUR_CD_onkeyup = function() {
    fn_DelChar3(this);
    if (txb_pISUR_CD.getValue() === "") {

    } else {
        if (window.event.keyCode === 13) {
            scwin.ins_search();
        } else {

        }
    }
};

/**
 * @method
 * @name cmb_pISUR_APPL_TP_CD_onselchange
 * @description cmb_pISUR_APPL_TP_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_pISUR_APPL_TP_CD_onselchange = function() {
    scwin.ins_search();
};

/**
 * @method
 * @name cmb_pPROC_onselchange
 * @description cmb_pPROC onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_pPROC_onselchange = function() {
    scwin.ins_search();
};
